E = dict(passage=M.P5, grp='H26-E')

add('HV-020', 'Ⅰ-C', '협상 발화의 기능', '중', p('\'Y동 대표\'의 발화에 대한 설명으로 적절하지 않은 것은?'),
    ['첫 발언에서 선호도 조사 결과를 근거로 도서관 설치를 요구하고 있다.', '㉠에서 Z동의 필요와 자신의 필요가 모두 충족될 수 있다며 상대를 설득하고 있다.', '무료 셔틀버스를 Z동까지 운행하는 것이 가능하다고 말하며 양보할 수 있는 부분을 제시하고 있다.', '마지막 발언에서 요금 할인을 조건으로 내세워 상대의 동의를 이끌어 내고 있다.', '체육 시설 이용 요금을 낮춰 달라는 요구를 거절하며 자신의 입장을 고수하고 있다.'], 5,
    ['① 적절하다. 시청의 선호도 조사에서 1순위였다고 했다.', '② 적절하다. 모두에게 이득이 되지 않을까요?라고 설득했다.', '③ 적절하다. 셔틀버스 운행을 양보로 제시했다.', '④ 적절하다. 도서관 설치에 동의하면 요금 할인을 적용하겠다고 했다.', '⑤ 적절하지 않다. 요금 요구를 거절하지 않고 동일한 수준의 요금 할인을 받아들였다.'], ref=[2], core='협상 발화는 요구·설득·양보·조건 제시 중 무엇인지 지문의 발화로 확인한다.', **E)

add('HV-021', 'Ⅰ-C', '협상의 단계와 전략', '중', p('\'Z동 대표\'의 협상 전략에 대한 설명으로 적절하지 않은 것은?'),
    ['선호도 조사 결과를 제시하여 체육 시설 설치의 필요성을 뒷받침하고 있다.', '상대가 제안한 체육 시설 활용 방안의 한계로 거리와 교통 문제를 지적하고 있다.', '상대에게 이익이 예상된다는 점을 들어 비용 부담을 제안하고 있다.', '상대가 양보한 뒤에 이용 요금 인하라는 추가 요구를 제시하고 있다.', '시청 담당자의 절충안을 수용하여 도서관 설치를 요구하고 있다.'], 5,
    ['① 적절하다. 선호도 조사에서 체육 시설을 가장 선호한다고 했다.', '② 적절하다. 거리가 멀고 교통편이 불편하다고 했다.', '③ 적절하다. 수익 증가가 예상되는 Y동의 비용 부담을 제안했다.', '④ 적절하다. 셔틀버스 제안 후 요금에 대한 부담을 낮춰 달라고 했다.', '⑤ 적절하지 않다. 시청 담당자는 절충안을 제시하지 않았고(버스 조정이 어렵다고만 했다) Z동 대표가 도서관 설치를 먼저 요구한 것도 아니다.'], ref=[2], core='협상 전략 문제는 지문에 없는 중재안·요구를 끌어들인 선택지를 거른다.', **E)

add('HV-022', 'Ⅰ-C', '협상 발화의 기능', '하', p('\'시청 담당자\'의 역할에 대한 설명으로 가장 적절한 것은?'),
    ['협상을 시작하며 참여자에게 감사를 표하고, 마지막에 타결 결과를 정리하며 후속 논의를 예고하고 있다.', '양측의 입장 차이를 줄이기 위해 새로운 절충안을 직접 제시하고 있다.', '버스 노선을 조정하겠다고 약속하여 Z동의 요구를 받아들이고 있다.', '선호도 조사 결과를 근거로 한쪽 동의 주장을 지지하고 있다.', '참여자들의 발언 순서를 정하여 협상을 진행하고 있다.'], 1,
    ['① 옳다. 첫 발언에서 감사를 전하고 마지막에 타결과 차후 논의를 밝혔다.', '② 옳지 않다. 절충안은 제시하지 않았다.', '③ 옳지 않다. 조정이 쉽지 않다고 했다.', '④ 옳지 않다. 어느 한쪽을 지지하지 않았다.', '⑤ 옳지 않다. 발언 순서를 지정한 발화가 없다.'], ref=[2], core='중재자의 발화 기능(안내·정리·제약 설명)을 구별한다.', **E)

add('HV-023', 'Ⅰ-C', '매체 자료의 작성과 활용', '중',
    p('〈보기〉는 위 협상을 보도한 기사의 일부이다. 협상 내용과 일치하는 것만을 〈보기〉에서 있는 대로 고른 것은?') +
    bogi(['ㄱ. Y동 대표는 선호도 조사에서 도서관이 1순위였음을 근거로 제시했다.', 'ㄴ. Z동 대표는 Y동의 체육 시설을 활용하는 방안에 처음부터 흔쾌히 동의했다.', 'ㄷ. 합의 내용에는 Y동 체육 시설 이용 요금의 할인 적용이 포함되었다.'], '보 기'),
    ['ㄱ', 'ㄴ', 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ'], 4,
    ['ㄱ. 일치한다. Y동 대표가 시청의 선호도 조사에서 1순위였다고 했다.', 'ㄴ. 일치하지 않는다. Z동 대표는 거리가 멀고 교통이 불편하다며 추가 조치가 있어야 한다고 했다.', 'ㄷ. 일치한다. Z동 주민에게 동일한 수준의 요금 할인을 적용하기로 했다.'], ref=[3], core='기사 내용 일치 문제는 각 진술의 근거 발화를 찾는다.', **E)
